from fastmcp import FastMCP
import asyncio

# Create a sub-server with math tools
math_server = FastMCP("math_tools")

@math_server.tool()
def add(a: float, b: float) -> float:
    """Add two numbers."""
    return a + b

@math_server.tool()
def subtract(a: float, b: float) -> float:
    """Subtract b from a."""
    return a - b

@math_server.tool()
def multiply(a: float, b: float) -> float:
    """Multiply two numbers."""
    return a * b

@math_server.tool()
def divide(a: float, b: float) -> float:
    """Divide a by b."""
    if b == 0:
        raise ValueError("Cannot divide by zero")
    return a / b

# Create the main server
main_server = FastMCP("main_server")

@main_server.tool()
def greet(name: str) -> str:
    """Greet someone."""
    return f"Hello, {name}!"

# Attach the math sub-server to the main server with "math" prefix
main_server.add_provider(math_server, namespace="math")

# Run the main server on stdio
if __name__ == "__main__":
